// Validates the commit message convention: `type(scope): emoji description`.
// See .claude/skills/conventional-commits/SKILL.md.
import { readFileSync } from 'node:fs';

const EMOJI_BY_TYPE = {
  build: '📦',
  chore: '🔧',
  ci: '👷',
  docs: '📝',
  feat: '✨',
  fix: '🐛',
  hotfix: '🚑️',
  perf: '⚡️',
  refactor: '♻️',
  revert: '⏪️',
  security: '🔒',
  style: '💄',
  test: '✅',
};
const MAX_HEADER_LENGTH = 72;

// Messages generated by git itself are allowed as they are.
const GIT_GENERATED = /^(Merge |Revert "|fixup! |squash! |amend! )/;

const HEADER =
  /^(?<type>[a-z]+)(?:\((?<scope>[a-z0-9-]+)\))?!?: (?<emoji>\S+) (?<description>.+)$/u;

const messageFile = process.argv[2];
if (!messageFile) {
  console.error('Usage: validate-commit-message.mjs <commit message file>');
  process.exit(1);
}

const header = readFileSync(messageFile, 'utf8')
  .split('\n')
  .find((line) => line.trim() !== '' && !line.startsWith('#'));

const fail = (reason) => {
  console.error(`✖ Invalid commit message: ${reason}`);
  console.error(`  "${header ?? ''}"`);
  console.error(
    '  Expected: type(scope): emoji description  (e.g. "feat(backend): ✨ add forms module")',
  );
  process.exit(1);
};

if (!header) fail('the message is empty');
if (GIT_GENERATED.test(header)) process.exit(0);

const match = HEADER.exec(header);
if (!match?.groups) fail('it does not follow "type(scope): emoji description"');

const { type, emoji, description } = match.groups;
const expectedEmoji = EMOJI_BY_TYPE[type];

if (!expectedEmoji) fail(`unknown type "${type}" (use ${Object.keys(EMOJI_BY_TYPE).join(', ')})`);

// Compare without the variation selector so "♻" and "♻️" are both accepted.
const stripVariation = (value) => value.replace(/️/g, '');
if (stripVariation(emoji) !== stripVariation(expectedEmoji)) {
  fail(`type "${type}" must use the ${expectedEmoji} emoji`);
}

if (!/^[a-z0-9]/.test(description)) fail('the description must start in lowercase');
if (description.endsWith('.')) fail('the description must not end with a period');
if ([...header].length > MAX_HEADER_LENGTH)
  fail(`the header is longer than ${MAX_HEADER_LENGTH} characters`);
